local _, A = ...
-- Quest-grounded geography: reference context, never player history.
local V = "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt"
local function P(slug, title, ids, body, names, related)
    return {id = "place:" .. slug, title = title, kind = "Place", body = body,
        sources = {V .. " " .. ids}, names = names, related = related}
end
A.RegisterLoreNotes({
    P("northshire-abbey", "Northshire Abbey", "#344; #3101",
        "Northshire Abbey housed a library tended by Brother Paxton, who borrowed books to copy for its shelves. It was also a place of training: Brother Sammuel introduced new paladins to their duties as Knights of the Silver Hand."),
    P("auberdine", "Auberdine", "#729; #730",
        "Auberdine served as a place to seek help for archaeological expeditions in Darkshore. Hollee returned there after hostile golems overran Prospector Remtravel's dig, while the expedition's distant sponsors worried over the lack of reports."),
    {id = "place:astranaar",
        title = "Astranaar",
        kind = "Place",
        body = "Astranaar is a night elf settlement and Alliance refuge in Ashenvale. Travelers arriving from Darkshore are directed here to offer help to a forest that remains beautiful but is no longer peaceful. Raene Wolfrunner seeks aid against its corruption, while the town's defenders watch the growing Thistlefur presence to the north. Horde planners also reckon with Astranaar: a route around the settlement would connect their outposts without granting the Alliance another advantage.\n\nThe forest's troubles reach individual homes as well as its defenses. Pelturas Whitemoon waits here for medicine for his gravely ill daughter, Relara. A healer's cure arriving from outside the town can matter as urgently to him as a report from the scouts. Astranaar is a community living with Ashenvale's afflictions, as well as a place from which to confront them.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #990 Trek to Ashenvale; #1133 Journey to Astranaar; #1054 Culling the Threat; #216 Between a Rock and a Thistlefur; #1020 Orendil's Cure", "https://vanilla-wow-archive.fandom.com/wiki/Darnassian"},
        names = {},
        related = {"region:417368656e76616c65"},
        setting = "Classic / Forever"},
    {id = "place:splintertree",
        title = "Splintertree Post",
        kind = "Place",
        body = "Splintertree Post is one of the Horde's outposts in Ashenvale. Senani Thunderheart welcomes adventurers to the Ashenvale Hunt, offering a way to prove themselves in a forest where the Horde is still extending its presence.\n\nThe post also serves the work of scouts and lumber camps. Warsong reports pass through it, and Pixel holds a shipment of saw blades needed at the logging camp. Even reaching the outpost can be dangerous: the hippogryph Sharptalon has long terrorized peons traveling from the nearby camps. Hunting trophies and workers' concerns meet at the same frontier settlement.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #235 The Ashenvale Hunt; #2 Sharptalon's Claw; #6543 The Warsong Reports; #6571 Warsong Supplies"},
        names = {},
        related = {"region:417368656e76616c65", "place:warsong-lumber-camp"},
        setting = "Classic / Forever"},
    P("zoramgar", "Zoram'gar Outpost", "#824; #909",
        "The Horde maintained Zoram'gar Outpost on the coast of the Zoram Strand. Je'neu Sancrea of the Earthen Ring studied the elements there, examining signs that even the water's powers had become corrupted."),
    {id = "place:menethil",
        title = "Menethil Harbor",
        kind = "Place",
        body = "Menethil Harbor is an Alliance port and stronghold on the western coast of the Wetlands. Its ships connect the Eastern Kingdoms with Auberdine and Theramore in Kalimdor, while the road through Dun Algaz links the harbor to Loch Modan. The town joins the dwarven lands to the Alliance's settlements across the sea, giving its docks an importance that reaches far beyond the marshes around them.\n\nThat inland connection is under threat. The Dragonmaw clan has occupied Dun Algaz, obstructing reinforcements while its chieftain Nek'rosh prepares catapults for a siege of Menethil. Captain Stoutfist seeks to break the encampment and destroy those engines before the harbor is attacked. Control of the road and the defense of the port are parts of the same struggle.\n\nMenethil is also a place to trace the fortunes of ships that never reached safety. The Third Fleet of Kul Tiras sank along the Wetlands coast with precious Lightforge Iron aboard; Glorin Steelbrow can help locate the metal and have it made into a weapon against the necromancer Morbent Fel. Karl Boran, meanwhile, awaits the missing Menethil Statuette, valuable cargo from the Blind Princess. These losses tie the harbor's daily concerns to wrecks scattered along its coast.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #270; #286", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #455 The Algaz Gauntlet; #465 Nek'rosh's Gambit; #942 The Absent Minded Prospector", "https://warcraft.wiki.gg/wiki/Menethil_Harbor (western coast; World of Warcraft section, original sea connections only)"},
        names = {},
        related = {"region:5765746c616e6473", "place:auberdine", "place:theramore"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "place:lakeshire",
        title = "Lakeshire",
        kind = "Place",
        body = "Lakeshire is a human town on Lake Everstill in the Redridge Mountains, governed by Magistrate Solomon. Blackrock orcs have taken Stonewatch Keep and raid the township, while the Shadowhide gnolls serve another enemy, the mage Morganth. Solomon seeks help beyond the town as its defenders face pressure on several fronts.\n\nHis appeals expose how strained Stormwind's protection has become. General Marcus Jonathan promises reinforcements once the king gives approval, but Darkshire cannot spare its Night Watch without leaving its own people defenseless. Lakeshire's requests for aid become questions about the kingdom itself: why are so many of its communities being left to stand alone?",
        sources = {"https://warcraft.wiki.gg/wiki/Lakeshire (geographic introduction)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #120 Messenger to Stormwind; #146 Messenger to Darkshire; #169 WANTED: Gath'Ilzogg; #180 WANTED: Lieutenant Fangore"},
        names = {},
        related = {"npc:solomon", "place:stonewatch", "region:5265647269646765204d6f756e7461696e73"},
        setting = "Classic / Forever"},
    P("darkshire", "Darkshire", "#56; #5",
        "The Night Watch defended Darkshire after Stormwind withdrew its commissioned guards. Undead threatened from Tranquil Gardens to the south, while the Scarlet Raven Tavern remained a source of cooked meals within the town."),
    {id = "place:raven-hill",
        title = "Raven Hill",
        kind = "Place",
        body = "Raven Hill is an abandoned town in western Duskwood, just south of the cemetery that bears its name. Calor's reports of moving shadows and a light in one of its buildings prompt Elaine Carevin to seek an investigation. Among the deserted houses hides Jitters, frightened, hungry and quick to insist that he means no harm.\n\nThe cemetery presents a less uncertain danger. Skeletons and plague-bearing undead gather there, stretching the Night Watch beyond its strength and threatening the people of Darkshire. Above the graves, Morbent Fel shelters in a house protected by magic. Sven Yorgen seeks his destruction, but defeating the necromancer requires a way through those defenses.",
        sources = {"https://warcraft.wiki.gg/wiki/Raven_Hill (location and original World of Warcraft section)", "https://classicdb.ch/?quest=163", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5 Jitters' Growling Gut; #55 Morbent Fel; #57-58 The Night Watch; #163 Raven Hill"},
        names = {"Raven Hill Cemetery"},
        related = {"region:4475736b776f6f64", "npc:jitters", "place:darkshire"},
        setting = "Classic / Forever"},
    {id = "place:moonbrook",
        title = "Moonbrook",
        kind = "Place",
        body = "Moonbrook is a town in southwestern Westfall, where Defias pillagers move through the streets above the Brotherhood's hidden base. Beneath a barn lies the entrance to the Deadmines. The People's Militia's struggle to recover the countryside leads toward the workings under the town.\n\nThose tunnels hold losses beyond the militia's immediate war. A cave-in left miners missing, and survivors seek their badges and union cards to bring answers to the families. Moonbrook's schoolhouse preserves another trace of its old life: the town registry lists it as Stalvan Mistmantle's last recorded address.",
        sources = {"https://warcraft.wiki.gg/wiki/Moonbrook (location and original WoW section; excludes later reconstruction)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #13 The People's Militia; #67 The Legend of Stalvan; #142 The Defias Brotherhood; #167 Oh Brother...; #168 Collecting Memories"},
        names = {},
        related = {"region:5765737466616c6c", "dungeon:deadmines", "group:peoples-militia"},
        setting = "Classic / Forever"},
    {id = "place:booty-bay",
        title = "Booty Bay",
        kind = "Place",
        body = "Booty Bay is a neutral goblin port at the southern tip of Stranglethorn Vale. Baron Revilgaz and the Blackwater Raiders run the town as part of the Steamwheedle Cartel, while its ships carry goods across the sea to Ratchet. Its merchants and wharfmasters connect two continents through the ordinary business of cargo lists, tools and promised deliveries. Fleet Master Seahorn commands the Blackwater Raiders beside the baron's commercial interests.\n\nThe Bloodsail Buccaneers challenge that hold on the coast. Their scouts gather near Booty Bay, and orders passing among their crews reveal preparations for an attack on the town. Seahorn seeks their charts and correspondence to uncover the plan and locate the captains directing it. The port's welcoming trade and its pirate rivalry coexist: the same harbor that draws merchants also gives its enemies a prize worth seizing.",
        sources = {"Original Booty Bay faction description, preserved at https://warcraft.wiki.gg/wiki/Booty_Bay (Revilgaz, Blackwater Raiders, Steamwheedle and Bloodsail rivalry); original World of Warcraft section for location and neutrality", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #595/#599/#604/#608 The Bloodsail Buccaneers; #1180 Goblin Sponsorship"},
        names = {},
        related = {"faction:steamwheedle", "faction:bloodsail", "place:ratchet"},
        setting = "Classic / Forever"},
    {id = "place:gadgetzan",
        title = "Gadgetzan",
        kind = "Place",
        body = "Gadgetzan is the Steamwheedle Cartel's trading town in Tanaris. Its goblins welcome customers from both the Horde and the Alliance, provided weapons stay sheathed; bruisers enforce the peace that keeps business moving. The town offers banks, an inn and a neutral auction house in a desert where even the essentials can be difficult to secure.\n\nWater is a constant concern. Wastewander nomads have seized wells and stolen supplies, while survey work seeks additional free sources beyond the wells the Wastewander control. Research farther into the desert uncovers a danger beyond banditry. Scrimshank's disappearance in the Gaping Chasm and Pestlezugg's analysis of insect parts lead to urgent warnings about the spreading insect threat. Some findings are serious enough to share beyond Gadgetzan, despite the instinct to turn a discovery into a commercial advantage.",
        sources = {"https://warcraft.wiki.gg/wiki/Gadgetzan_Times/Gadgetzan%3A_The_Jewel_of_Tanaris", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #1690 Wastewander Justice; #1707 Water Pouch Bounty; #992 Gadgetzan Water Survey; #10 The Scrimshank Redemption; #113 Insect Part Analysis"},
        names = {},
        related = {"faction:steamwheedle", "region:54616e61726973"},
        setting = "Classic / Forever"},
    P("everlook", "Everlook", "#4808; #5047",
        "Everlook was a town in Winterspring where researchers could seek specialist craftsmanship. Felnok Steelspring made engineering components for dragon studies, and Malyfous Darkhammer assessed the uses of unusual monster remains."),
    {id = "place:theramore",
        title = "Theramore",
        kind = "Place",
        body = "Theramore is Jaina Proudmoore's island city and harbor on the coast of Dustwallow Marsh. Survivors who followed her from Lordaeron made a new home here after the Third War. Her willingness to work with the Horde has not erased the dangers and suspicions surrounding that peace.\n\nThe city's guards struggle to hold their positions in the marsh. Watchtowers have been abandoned by deserters, and Captain Garran Vimes pursues reports of soldiers who have gone missing or turned to raiding supplies. An inquiry that begins with a missing diplomat reveals the kidnapping of Stormwind's king. With Jaina's knowledge, Archmage Tervosh helps investigators pursue Private Hendel, the man placed aboard the king's ship. The harbor is a foothold for the Alliance in Kalimdor, while its scattered garrison and delicate relations with its neighbors leave much for its leaders to manage.",
        sources = {"https://warcraft.wiki.gg/wiki/Jaina_Proudmoore", "https://warcraft.wiki.gg/wiki/A_Blaze_of_Glory", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #1285 Daelin’s Men; #1286 The Deserters; #1287 The Deserters; #1241 and #1250 The Missing Diplomat; #1265 The Missing Diplomat; #1266 The Missing Diplomat"},
        names = {"Theramore Isle"},
        related = {"npc:jaina", "npc:tervosh", "region:4475737477616c6c6f77204d61727368"},
        setting = "Classic / Forever"},
    P("brackenwall", "Brackenwall Village", "#1201; #1238",
        "Brackenwall Village housed Horde agents keeping watch on Theramore. The spying went both ways: Alliance infiltrators east of the village reported its movements despite the uneasy truce between the factions."),
    {id = "place:camp-mojache",
        title = "Camp Mojache",
        kind = "Place",
        body = "Camp Mojache is a Horde settlement in Feralas, serving as a base for expeditions into the forest. Rok Orhan receives warriors sent to confront the growing Gordunni presence, while the tauren elder Talo Thornhoof seeks help with a dangerous undertaking in Dire Maul. The camp's concerns extend well beyond its immediate defenses.\n\nHadoken Swiftstrider investigates the increasingly coordinated attacks of the Woodpaw gnolls. Their battle plans reveal that most of their strength is directed south, against an enemy marked as an insect. The gnolls are fighting a second war. Further reports about the Zukk'ash are sent to Orgrimmar, where Zilzibin Drumlore identifies them as silithid and warns that the Horde has underestimated the threat. What begins as a local defense becomes evidence of a danger reaching beyond Feralas.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #2981 A Threat in Feralas; #7492 Camp Mojache; #2902 Woodpaw Investigation; #2903 The Battle Plans; #7732 Zukk'ash Report"},
        names = {},
        related = {"region:466572616c6173", "dungeon:dire-maul", "group:silithid"},
        setting = "Classic / Forever"},
    P("feathermoon", "Feathermoon Stronghold", "#2867; #2869",
        "General Shandris Feathermoon directed the stronghold's efforts in Feralas. The Hatecrest naga on Sardor Isle were an immediate concern, with officers fearing that their presence would grow into an attempt to control the island.", {"Feathermoon"}),
    P("shadowprey", "Shadowprey Village", "#5386; #5501",
        "Shadowprey was a troll village known for its fishermen, including Jinar'Zillen and his Bloodbelly fish. Caravans also brought kodo bones there for sale, connecting the settlement to trade farther inland."),
    P("nijels-point", "Nijel's Point", "#1453",
        "Nijel's Point was a small camp tucked into the mountains of northern Desolace. Kreldig Ungor worked there for the Reclaimers, finding lost possessions and other missing things for customers able to pay."),
    P("revantusk", "Revantusk Village", "#7815; #7828",
        "Life at Revantusk Village depended on hunting and fishing in the Hinterlands. Silvermane wolves ambushed hunters, while the saltwater snapjaws stole bait and broke fishing lines along the coast.", nil, {"faction:revantusk"}),
    {id = "place:aerie-peak",
        title = "Aerie Peak",
        kind = "Place",
        body = "Aerie Peak is the Wildhammer dwarves' home in the Hinterlands. Their people settled here after the War of the Three Hammers left Grim Batol uninhabitable. The settlement is renowned for its gryphon aviary and skilled pilots; travelers seeking their help are directed to Falstad Wildhammer.\n\nLife at the Peak involves defending that home as well as taking wing from it. Troll attacks occupy Falstad's attention, and the Wildhammers seek to extend their influence around Skulk Rock. The Horde's abandoned positions there are now overrun by slimes and oozes, making even an apparently humble cleanup part of the clan's plans for the surrounding land.",
        sources = {"https://warcraft.wiki.gg/wiki/Aerie (independently written introduction and history overview)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #1449 To The Hinterlands; #2877 Skulk Rock Clean-up"},
        names = {},
        related = {"faction:wildhammer", "npc:falstad", "event:three-hammers"},
        setting = "Classic / Forever"},
    P("hammerfall", "Hammerfall", "#655; #638",
        "Hammerfall stood where orcs had once been held captive and where Orgrim Doomhammer fell during the fight to free them. The Horde later established itself there again; for survivors such as Gor'mul, the place carried painful memories."),
    P("refuge-pointe", "Refuge Pointe", "#634",
        "Refuge Pointe was an Alliance camp in the Arathi Highlands after Stromgarde's fall. Captain Nials refused to spare its soldiers for Dun Modr, believing their duty lay in retaking their own city first."),
    {id = "place:stromgarde",
        title = "Stromgarde",
        kind = "Place",
        body = "Stromgarde is a ruined human stronghold in the Arathi Highlands, divided among defenders and enemies. Boulderfist ogres occupy part of the city, while Syndicate agents hold one of the sigils protecting the Trollbane tomb. Prince Galen Trollbane remains in a chapel within the militia-held districts.\n\nAt Refuge Pointe, Captain Nials refuses to spare soldiers for other battles while Stromgarde remains fallen. Its defenders hope to raise their king's banner again. The dead also draw the attention of outsiders: with Thoras Trollbane gone, Vol'jin seeks the legendary sword Trol'kalar from his tomb for a coming struggle against the trolls of Zul'Gurub.",
        sources = {"https://classicdb.ch/?quest=679", "https://classicdb.ch/?quest=639", "https://classicdb.ch/?quest=644", "https://classicdb.ch/?quest=634", "https://classicdb.ch/?quest=638"},
        names = {"Stromgarde Keep"},
        related = {"place:refuge-pointe", "faction:kingdom-stromgarde", "relic:trolkalar"},
        setting = "Classic / Forever"},
    P("thorium-point", "Thorium Point", "#8858",
        "At Thorium Point in the Searing Gorge, Oilfist paid for samples from the immense insect colossi. He believed their chitin could be fashioned into exceptionally strong armor, turning distant battlefield remains into a smith's research material."),
    P("morgans-vigil", "Morgan's Vigil", "#4322",
        "Marshal Maxwell received reports at Morgan's Vigil during the effort to free Marshal Windsor from Blackrock Depths. The outpost was a link between the prison rescue and Windsor's planned confrontation in Stormwind."),
    P("flame-crest", "Flame Crest", "#4324; #4907",
        "Flame Crest was a cave northwest of Dreadmaul Rock in the Burning Steppes. Yuka Screwspigot searched for her wayward brother from there, while Tinkee Steamboil pursued dangerous studies of dragons."),
    P("chillwind", "Chillwind Camp", "#5066",
        "Commander Ashlam Valorfist established his base at Chillwind Camp north of the Alterac Mountains. Stormwind's call to arms directed volunteers there to confront the Scourge threatening the Plaguelands frontier."),
    P("cenarion-hold", "Cenarion Hold", "#8275; #8276",
        "Cenarion Hold gathered support for the Cenarion Circle's campaign against the silithid in Silithus. Its emissaries called on both Alliance and Horde adventurers, with Windcaller Proudhorn receiving those who answered."),
    P("marshals-refuge", "Marshal's Refuge", "#3845; #4491",
        "Marshal's Refuge sheltered travelers and explorers in Un'Goro Crater. Spraggle waited there for the missing Ringo, whose exploration had left him suffering from the crater's intense heat."),
    P("nighthaven", "Nighthaven", "#26; #27",
        "Nighthaven was a village in Moonglade where Dendrite Starblaze of the Cenarion Circle instructed druids. His lessons in aquatic form required students to demonstrate both practical skill in water and an understanding of the form itself."),
    P("dark-portal", "The Dark Portal", "#1421; #1425",
        "The Dark Portal in the Blasted Lands remained a focus of the Alliance's vigilance. Nethergarde Keep watched over it, and its wizards needed supplies and reagents to continue research tied to the portal's dangers.", {"Dark Portal"}),
    P("great-lift", "The Great Lift", "#1196; #4881",
        "The Great Lift connected the southern edge of the Barrens with Thousand Needles. Beyond that descent lay scattered posts and hunting camps, including Kanati Greycloud's camp southwest of the lift.", {"Great Lift"}),
    P("nesingwarys-expedition", "Nesingwary's Expedition", "#201; #187",
        "Hemet Nesingwary's hunters camped upriver from the Venture Company's mining operation on Lake Nazferiti. Their hunts tested skill against Stranglethorn's wildlife, while neighboring traders wondered whether the well-connected expedition would be a threat or a customer."),
    {id = "place:blackrock-mountain",
        title = "Blackrock Mountain",
        kind = "Place",
        body = "Blackrock Mountain rose between the Searing Gorge and the Burning Steppes, a volcanic stronghold with rival powers above and below. The Dark Iron dwarves held Blackrock Depths, while Ragnaros lurked farther down in the Molten Core. Blackrock Spire rose toward Nefarian's lair, where black dragons sheltered the forces opposing the Firelord.\n\nFor Horde investigators, the danger first appeared as a disturbance among the elements. The trail from Overmaster Pyron to Lord Incendius revealed Ragnaros as the power behind the corruption. Elsewhere inside the mountain, Lothos Riftwaker offered a way through a hidden rift to the Molten Core. The passages through the mountain brought adventurers toward the seats of both its dwarven and draconic powers.",
        sources = {"https://warcraft.wiki.gg/wiki/Blackrock_Mountain", "https://worldofwarcraft.blizzard.com/en-us/news/23302788", "https://classicdb.ch/?quest=3906", "https://classicdb.ch/?quest=3907", "https://classicdb.ch/?quest=7848"},
        names = {},
        related = {"dungeon:blackrock-depths", "dungeon:blackrock-spire", "dungeon:molten-core"},
        setting = "Classic / Forever"},
    P("crystal-lake", "Crystal Lake", "#112",
        "Crystal Lake lay just east of Goldshire, with murlocs living nearby. Their stores of crystal kelp interested local alchemy: the plant could serve as an ingredient in an invisibility liquor."),
    P("jasperlode", "Jasperlode Mine", "#47; #60",
        "Kobolds occupied Jasperlode Mine in Elwynn. Their gold dust drew a trader's attention, while the wax from their large candles was sought for a Stormwind apothecary."),
    P("eastvale", "Eastvale Logging Camp", "#52; #59",
        "Eastvale Logging Camp faced frequent attacks from increasingly aggressive wolves and bears. Sara Timberlain worked there under a Stormwind Army commission, supplying cloth and leather armor to those bearing the army's markers."),
    P("stone-cairn", "Stone Cairn Lake", "#11; #45",
        "Riverpaw gnolls threatened the country near Stone Cairn Lake, and a murloc village stood along its eastern shore. The disappearance of Footman Rolf Hartford made the lake part of the guards' search for their missing comrades."),
    P("brackwell", "Brackwell Pumpkin Patch", "#88; #123",
        "The Brackwells kept their prize-winning sow Princess at the pumpkin patch in eastern Elwynn. The area also appeared in a suspicious gold-delivery schedule that pointed Marshal Dughan toward the mysterious Collector."),
    P("jangolode", "Jangolode Mine", "#12; #142",
        "Defias trappers were reported around Jangolode Mine in Westfall. A messenger traveled the roads linking it with Moonbrook and the Gold Coast Quarry, making those routes valuable to the militia's investigation of the Brotherhood."),
    P("gold-coast-quarry", "Gold Coast Quarry", "#13; #142",
        "The Gold Coast Quarry lay near Westfall's shore, west of Sentinel Hill. Defias pillagers operated there, and the roads connecting it to other occupied sites carried messages the People's Militia hoped to intercept."),
    P("saldeans-farm", "Saldean's Farm", "#36; #22",
        "The Saldeans remained in Westfall while neighbors such as the Furlbrows prepared to leave the dangerous countryside. Salma's recipes and shared meals preserved some of the farmland's ordinary life amid the upheaval."),
    P("frostmane-hold", "Frostmane Hold", "#287; #1678",
        "Frostmane Hold was a troll-filled cave southwest of Brewnall Village. Its numbers alarmed dwarven scouts, and the formidable troll Vejrek lived in the foothills just south of the hold."),
    P("golbolar", "Gol'Bolar Quarry", "#433; #2239",
        "Troggs poured out as the miners of Gol'Bolar Quarry dug deeper, wrecking equipment and forcing the workers out. The quarry also figured in the route of an armored steam tank carrying shipments back to Ironforge."),
    P("steelgrills-depot", "Steelgrill's Depot", "#400; #317",
        "Beldin Steelgrill's workshop northeast of Kharanos repaired siege engines. Veteran pilots gathered there, and maintaining their tanks demanded a steady supply of tools as well as provisions for long missions."),
    P("brewnall", "Brewnall Village", "#287; #318",
        "Brewnall Village stood on the western bank of Iceflow Lake. Rejold Barleybrew experimented with potent drinks there; his Evershine could warm a traveler or give a siege engine's furnace a brief burst of power."),
    P("wellspring-lake", "Wellspring Lake", "#923",
        "Timberlings around Wellspring Lake in northern Teldrassil showed severe signs of corruption. The poisonous growths on their bodies became part of the effort to understand and cleanse the sickness afflicting the new land."),
    P("starbreeze", "Starbreeze Village", "#475",
        "Gaerolas Talvethren, guardian of the sleeping Druids of the Talon, was expected to send reports from Starbreeze Village. When word failed to arrive, Athridas feared for the sleepers in Ban'ethil and sent for news."),
    P("gnarlpine-hold", "Gnarlpine Hold", "#486",
        "Gnarlpine Hold lay in southwestern Teldrassil and sheltered Ursal the Mauler. Athridas held Ursal responsible for the plight of the sleeping Druids of the Talon, linking the hold to the effort to complete the ritual of awakening."),
    P("oracle-glade", "The Oracle Glade", "#934",
        "The Oracle Tree sheltered the first and most powerful of Teldrassil's moonwells. Water from this well was sought during the investigation of the troubles that had accompanied the raising of the new World Tree.", {"Oracle Glade"}),
    P("ruttheran", "Rut'theran Village", "#3022",
        "Rut'theran was a small village in southern Teldrassil. Erelas Ambersky tended hippogryph eggs there, helping them hatch and training the young as part of an effort to sustain their population."),
    P("stonewatch", "Stonewatch Keep", "#20; #19",
        "Blackrock orcs from the Burning Steppes claimed Stonewatch Keep and used it to threaten northern Redridge. Outrunners led by Tharil'zun ambushed the approaches, tightening the pressure on Lakeshire."),
    P("tranquil-gardens", "Tranquil Gardens Cemetery", "#56; #57",
        "Tranquil Gardens lay south of Darkshire, where skeletal warriors and mages troubled the town's defenders. The Night Watch treated its undead infestation as part of the wider danger spreading through Duskwood.", {"Tranquil Gardens"}),
    {id = "place:dun-modr",
        title = "Dun Modr",
        kind = "Place",
        body = "Dun Modr is a fortified dwarven town in the northern Wetlands, just south of the Thandol Span. Dark Iron dwarves seized it after their attack on the bridges. Longbraid's regiment, already battered by the ambush, could not regroup before the town was lost.\n\nThe survivors hold on nearby while the wounded Harlo recovers in Menethil. Longbraid seeks a chance to strike back at the Dark Irons and their warlock leader, Balgaras the Foul, but promised reserves have not arrived. An appeal to Refuge Pointe brings little relief: its Alliance defenders are committed to retaking Stromgarde and cannot abandon the Highlands to help.",
        sources = {"https://classic-wow-archive.fandom.com/wiki/Dun_Modr", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #303 The Dark Iron War; #304 A Grim Task; #472 Fall of Dun Modr; #634 Plea To The Alliance"},
        names = {},
        related = {"place:thandol-span", "faction:dark-iron", "place:refuge-pointe"},
        setting = "Classic / Forever"},
    {id = "place:thandol-span",
        title = "The Thandol Span",
        kind = "Place",
        body = "The Thandol Span is a pair of great stone bridges joining the Wetlands to the Arathi Highlands. Built by the dwarves, the crossing carries a vital northern supply route. Dark Iron attacks destroyed its western bridge, killing defenders; Dun Modr fell soon afterward.\n\nThe danger to the surviving bridge has not passed. Ebenezer Rustlocke, sent to scout the eastern crossing, died in a Dark Iron ambush. A parchment beside him reveals another cache of explosives across the Span, arranged by Kam Deepfury. With reinforcements still absent and Refuge Pointe unable to spare troops, the dwarven survivors depend on outside help to keep their last crossing open.",
        sources = {"https://wowpedia.fandom.com/wiki/Thandol_Span (geographic introduction only)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #303 The Dark Iron War; #304 A Grim Task; #631-633 The Thandol Span; #634 Plea To The Alliance"},
        names = {"Thandol Span"},
        related = {"place:dun-modr", "region:41726174686920486967686c616e6473", "region:5765746c616e6473"},
        setting = "Classic / Forever"},
    P("dun-garok", "Dun Garok", "#541; #517",
        "Dun Garok was a dwarven barracks along Thoradin's Wall in southeastern Hillsbrad, led by Captain Ironhill. The Forsaken targeted both its military strength and its stores, seeking a keg of Shindigger Stout for a plague experiment."),
    {id = "place:durnholde",
        title = "Durnholde Keep",
        kind = "Place",
        body = "Durnholde Keep stood in the Hillsbrad Foothills, southeast of Tarren Mill. After the Second War, it controlled the orc internment camps. Aedelas Blackmoore raised Thrall there as a slave and gladiator. With Taretha Foxton's help, Thrall escaped; he later returned at the head of the free orcs, defeated Blackmoore and called on the earth to bring the fortress down.\n\nThe ruins became a Syndicate stronghold. Warriors sent by the Warchief to investigate were overwhelmed, leaving Drull and Tog'thar captive and their leader Gol'dir taken elsewhere. Krusk sought help for his comrades, while the Forsaken at Tarren Mill called for the destruction of the Syndicate gathering behind the broken walls.",
        sources = {"Christie Golden, Warcraft: Lord of the Clans (2001), captivity/escape and final Durnholde chapters", "https://warcraft.wiki.gg/wiki/Durnholde_Keep", "https://classicdb.ch/?quest=498", "https://classicdb.ch/?quest=549"},
        names = {"Durnholde"},
        related = {"npc:thrall", "faction:syndicate", "region:48696c6c736272616420466f6f7468696c6c73"},
        setting = "Classic / Forever"},
    P("purgation-isle", "Purgation Isle", "#8965",
        "Purgation Isle lay off the southern coast of Hillsbrad, haunted by the banished dead. The ogre necromancer Kormok had delighted in calling up their souls, making their ashes a potent focus for summoning his own spirit."),
    {id = "place:northfold",
        title = "Northfold Manor",
        kind = "Place",
        body = "Northfold Manor is a farmstead in the northwestern Arathi Highlands occupied by the Syndicate. Its position matters to the struggle for Stromgarde: Syndicate activity from the manor threatens the supply route from Southshore while Stromgarde's soldiers face both Syndicate fighters and ogres. Captain Nials seeks help breaking that pressure so supplies can reach the defenders.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #681, #671", "https://warcraft.wiki.gg/wiki/Northfold_Manor (original location)"},
        names = {},
        related = {"region:41726174686920486967686c616e6473", "place:southshore", "faction:syndicate"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "place:faldirs-cove",
        title = "Faldir's Cove",
        kind = "Place",
        body = "Faldir's Cove is a sheltered anchorage on the Arathi coast where a Blackwater Raiders treasure expedition came to grief. O'Breen brought the Harbinger in safely, but the sea suddenly fell as the Spirit of Silverpine and Maiden's Folly followed. Both ships struck the reef and sank. Captain Steelgut remembers naga attacking the survivors of his own lost vessel.\n\nThe expedition's work now includes recovering the wrecks' charts and logs before their secrets fall into other hands. Yet the search for elven treasure continues, aided by enchanted goggles. With Daggerspine naga gathering offshore, the stranded sailors must also defend the cove long enough to sail back to Booty Bay.",
        sources = {"https://classicdb.ch/?quest=663", "https://classicdb.ch/?quest=662", "https://classicdb.ch/?quest=664", "https://classicdb.ch/?quest=665", "https://classicdb.ch/?quest=667", "https://classicdb.ch/?quest=670"},
        names = {"Faldir’s Cove"},
        related = {"faction:blackwater-raiders", "place:booty-bay", "region:41726174686920486967686c616e6473"},
        setting = "Classic / Forever",
        autoLink = true},
    P("goshek", "Go'Shek Farm", "#657",
        "Apothecary Jorell conducted deadly experiments at Go'Shek Farm. Alliance investigators sought his remaining research before it could be sent to Tarren Mill, tying the farm to fears of a new plague."),
    P("gromgol", "Grom'gol Base Camp", "#568",
        "Grom'gol was the Warchief's base camp in Stranglethorn's jungle. Its commander was charged with protecting Horde travelers and maintaining a supply route to Stonard, a task complicated by the raptors outside the camp.", {"Grom'gol"}),
    P("rebel-camp", "Rebel Camp", "#198; #329",
        "Lieutenant Doren's followers camped near the northern entrance to Stranglethorn, opposing Kurzen and his men. Supplies from the goblins helped their defense, while evidence of a spy within their own camp threatened that fragile security."),
    P("moshogg", "Mosh'Ogg Ogre Mound", "#591",
        "The ogre mage Mai'Zoth held the Mind's Eye deep within the Mosh'Ogg mound. His already formidable magic and possession of the artifact made the place central to the Darkspears' attempt to save Yenniku."),
    P("tiragarde", "Tiragarde Keep", "#784",
        "Tiragarde Keep fell when Admiral Proudmoore's attack on Durotar was repelled. His reserves later returned under Lieutenant Benedict and retook it, renewing the danger to the orcs' homeland."),
    P("razorwind", "Razorwind Canyon", "#834",
        "Dustwind harpies in Razorwind Canyon seized supplies intended for work in Durotar. Rezlak, one of Gazlowe's workers, needed the stolen shipment back before the building effort could continue."),
    P("thunder-ridge", "Thunder Ridge", "#806",
        "Fizzle Darkstorm and his Burning Blade followers camped within Thunder Ridge. Their presence gave the cult a foothold in Durotar and prompted a campaign to drive the warlock and his followers out."),
    P("venture-co-mine", "Venture Co. Mine", "#765",
        "Supervisor Fizsprocket directed Venture Company plans from the mine in Mulgore. Documents from a ravaged caravan implicated the company in efforts to drive the tauren from their land so that it could exploit the area freely."),
    {id = "place:camp-taurajo",
        title = "Camp Taurajo",
        kind = "Place",
        body = "Camp Taurajo was a tauren outpost in the southern Barrens, near the pass to Mulgore. Travelers could rest there or continue their training: Jorn Skyseer guided those walking the hunter's path, while Ruga Ragetotem called warriors to his trial. Orc grunts shared the camp and fought the neighboring quilboar.\n\nThat work carried a cost. Dogran was badly wounded on a mission and remained captive in a quilboar camp; his comrades sought a healing draught from Malaka'jin before attempting to bring him back. Within Taurajo, the caged quilboar Mangletooth offered another route into the conflict, bargaining for attacks on the Bristlebacks even as his own tribe left him imprisoned.",
        sources = {"https://warcraft.wiki.gg/wiki/Camp_Taurajo", "https://classicdb.ch/?quest=3261", "https://classicdb.ch/?quest=1823", "https://classicdb.ch/?quest=1510", "https://classicdb.ch/?quest=1515", "https://classicdb.ch/?quest=878"},
        names = {},
        related = {"region:5468652042617272656e73", "region:4d756c676f7265", "faction:bristleback"},
        setting = "Classic / Forever"},
    P("lushwater", "Lushwater Oasis", "#852",
        "Hezrul Bloodmark led the Barrens' Kolkar centaur from Lushwater Oasis. Horde defenders regarded his leadership as the force holding a dangerous enemy together and made him a particular target."),
    P("forgotten-pools", "The Forgotten Pools", "#850",
        "Barak Kodobane camped near the Forgotten Pools, one of the new leaders rallying the Kolkar in the Barrens. His rise alarmed Horde defenders who had previously faced a less organized centaur threat.", {"Forgotten Pools"}),
    P("stagnant-oasis", "The Stagnant Oasis", "#851",
        "The Stagnant Oasis held a Kolkar command tent used as Verog the Dervish's base. Verog roamed widely, but an alarm raised by the centaur at the oasis could bring him back to defend it.", {"Stagnant Oasis"}),
    {id = "place:northwatch",
        title = "Northwatch Hold",
        kind = "Place",
        body = "Northwatch Hold is an Alliance human fortress on the Barrens' Merchant Coast, held by troops from Theramore. Captain Fairmount and her cannoneers command guns that threaten passing ships. In Ratchet, Captain Thalo'thas Brightsun blames their indiscriminate fire for losses to his fleet and seeks retaliation.\n\nWithin the hold, Gilthares Firebough waits as a prisoner. He says his captors sank the vessel on which he served as a deckhand, a moonshine transport sailing between Ratchet and Booty Bay. The only survivor, he was branded a threat to the Alliance; his immediate hope is simply to escape back to Ratchet.",
        sources = {"https://classic-wow-archive.fandom.com/wiki/Northwatch_Hold", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #891 The Guns of Northwatch; #898 Free From the Hold"},
        names = {},
        related = {"place:ratchet", "place:theramore"},
        setting = "Classic / Forever"},
    P("boulder-lode", "Boulder Lode Mine", "#896",
        "The Venture Company operated Boulder Lode Mine northeast of the Sludge Fen. News that a miner had discovered an enormous emerald quickly reached Ratchet's wharfmaster and the buyers he hoped to interest."),
    {id = "place:sun-rock",
        title = "Sun Rock Retreat",
        kind = "Place",
        body = "Sun Rock Retreat is a Horde settlement in the central Stonetalon Mountains, sheltered among the peaks south of Mirkfallon Lake. Tauren and orcs make it a base for travel and trade in the mountains and for efforts to repair the harm caused by the Venture Company's logging. The surrounding land gives the retreat's defenders two closely connected concerns: protecting those who pass through it and restoring the forests on which life here depends.\n\nTammra Windfield works toward that recovery through the blessings of the Earthmother. She seeks Gaea seeds from the shores of Mirkfallon Lake and imbues them with shamanistic power to hasten their growth. The enchanted seeds are intended for the scarred Charred Vale, where harpies and angry fire elementals still threaten new life. Tammra hopes their growth will resist corruption and allow a forest to return; the healing of Stonetalon remains unfinished.\n\nThe routes to the retreat also have dangers closer to hand. Maggran Earthbinder offers a bounty on Besseleth, the great spider whose brood occupies Sishir Canyon. He survived an attack himself and fears for travelers along Webwinder Path after dark, when Besseleth and her young hunt.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6284", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #6301 Cycle of Rebirth; #6381 New Life", "https://warcraft.wiki.gg/wiki/Sun_Rock (lead location, races and pre-Cataclysm hub; Removed NPCs)", "https://classicdb.ch/?quest=6301 (giver, location and description)"},
        names = {},
        related = {"region:53746f6e6574616c6f6e204d6f756e7461696e73", "faction:venture-company"},
        setting = "Classic / Forever",
        autoLink = true},
    P("stonetalon-peak", "Stonetalon Peak", "#1056",
        "Keeper Albagorm waited at Stonetalon Peak for those sent to serve the forest spirits. The route from Ashenvale passed through Talondeep Path and Windshear Crag before climbing north beyond Cragpool Lake."),
    P("charred-vale", "The Charred Vale", "#1057",
        "Industrialists burned the forest of the Charred Vale, leaving its protectors to plan a difficult restoration. Bloodfury harpies then occupied the damaged land and prevented efforts to begin regrowth.", {"Charred Vale"}),
    P("mystral-lake", "Mystral Lake", "#25",
        "Hostile water elementals around Mystral Lake disrupted transport between Ashenvale and Stonetalon. A gazebo on the lake also offered a view of an Alliance outpost, attracting the interest of Horde scouts."),
    {id = "place:maestras-post",
        title = "Maestra's Post",
        kind = "Place",
        body = "Maestra's Post is a small night elven camp in western Ashenvale, with a tower and a large building. Among its few inhabitants is Delgren the Purifier, a human paladin helping the Sentinels confront demons and undead.\n\nHis apprentice Balthule sends reports of the Dark Strand cult's growing threat. Though the night elves' ways were unfamiliar to Delgren at first, he has come to respect them as allies. The post brings that alliance into daily practice, as warnings from the forest reach a defender willing to act on them.",
        sources = {"https://classic-wow-archive.fandom.com/wiki/Maestra%27s_Post (original camp geography and inhabitants)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #967 The Tower of Althalaxx"},
        names = {},
        related = {"region:417368656e76616c65"},
        setting = "Classic / Forever"},
    {id = "place:freewind",
        title = "Freewind Post",
        kind = "Place",
        body = "Freewind Post is a tauren settlement raised above the floor of Thousand Needles on a steep mesa. A wooden lift and bridges connect its inhabitants with the canyon below and the neighboring heights. The roads that supply this refuge are dangerous: centaur attacks have intensified, and a raided caravan has left no survivors. Cliffwatcher Longhorn calls for retaliation against the nearby raiders.\n\nThe settlement also receives travelers carrying out sacred work. A phial of moonwell water is brought to Rau Cliffrunner here as part of an effort to reach a relic guarded by the centaur. Other warnings concern the Grimtotem, whose unusual behavior adds to the uncertainty along the road. Freewind is a place to rest above the canyon, but its height does not remove it from the conflicts below.",
        sources = {"https://wowpedia.fandom.com/wiki/Freewind_Post", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #4542 Message to Freewind Post; #4841 Pacify the Centaur; #1195–1196 The Sacred Flame"},
        names = {},
        related = {"region:54686f7573616e64204e6565646c6573", "faction:grimtotem"},
        setting = "Classic / Forever"},
    P("highperch", "Highperch", "#1135",
        "Highperch in Thousand Needles was home to wyverns with unusually valuable venom. Hunters sought their venom sacs even though the animals were better known elsewhere as mounts tamed by the orcs."),
    P("ghost-walker", "Ghost Walker Post", "#1362; #1432",
        "Horde agents at Ghost Walker Post studied the centaur clans of Desolace and planned how to weaken them. The post also supported efforts against the local demons, whose presence threatened to suggest a renewed pact between the Horde and the Legion."),
    P("kodo-graveyard", "Kodo Graveyard", "#5501; #1432",
        "The great Kodo Graveyard lay south of Ghost Walker Post. Its bones drew commercial interest as raw materials for furniture, instruments and even blasting powder, with caravans carrying them onward to Shadowprey Village."),
    P("valley-of-bones", "Valley of Bones", "#261",
        "Undead ravagers haunted the Valley of Bones in southern Desolace. Brother Anton of the Scarlet Crusade used the struggle against them as a test for those seeking the order's approval."),
    P("nethergarde", "Nethergarde Keep", "#1425; #1364",
        "Nethergarde Keep stood in the northern hills of the Blasted Lands, keeping watch over the Dark Portal. Its researchers sought supplies and writings such as Khadgar's essays on dimensional convergence to support their work."),
    P("dustbelch", "Dustbelch Grotto", "#733",
        "Dustbelch Grotto was a major ogre camp in the Badlands. The ogres' supply of scrap metal attracted the attention of nearby explorers who lacked materials for their own camp's defenses and equipment."),
    P("uldum-gates", "Gates of Uldum", "#2946",
        "The sealed gates of Uldum had a pedestal capable of calling forth a Stone Watcher. Miniature discs from Uldaman could activate it, but the guardian required the missing Plates of Uldum before entry could be granted."),
    P("lost-rigger", "Lost Rigger Cove", "#4005",
        "A stone circle on the easternmost peninsula of Lost Rigger Cove provided a place to summon Aquementas. The creature's power could transform gathered materials into a totem capable of challenging Blazerunner's protection."),
    P("steamwheedle-port", "Steamwheedle Port", "#648",
        "Steamwheedle Port was a destination on the Tanaris coast used in Oglethorpe Obnoticus's recovery plans. He chose its open ground as a place where his damaged homing robot could prepare to take off for repairs."),
    P("gaping-chasm", "The Gaping Chasm", "#10; #113 Insect Part Analysis",
        "Surveyor Scrimshank disappeared while investigating the insects of the Gaping Chasm. His missing equipment became vital evidence for researchers trying to understand a threat that might reach far beyond the surrounding desert.", {"Gaping Chasm"}),
    P("noxious-lair", "The Noxious Lair", "#82",
        "The creatures of the Noxious Lair drained pools that had once held water in Tanaris. Samples from the Centipaar there gave Alchemist Pestlezugg a chance to investigate insects unlike any he had previously studied.", {"Noxious Lair"}),
    {id = "place:jinthaalor",
        title = "Jintha'Alor",
        kind = "Place",
        body = "Jintha'Alor is the Vilebranch capital in the southeastern Hinterlands, a forest-troll stronghold rising toward a summit altar. Vile Priestess Hexx's rites sustain its warriors: Primal Torntusk warns that vessels of tainted blood fill them with the blood god's power and drive them to madness.\n\nIts heights also conceal prisoners. Primal's spies report that the captive Elder Torntusk faces sacrifice to Hakkar. The young gryphon Sharpbeak is held in a cage nearby, with Hexx keeping its key. The Wildhammers seek his release so he can return to his parents at Aerie Peak. For both the Revantusk and the Wildhammers, the climb into Jintha'Alor is a struggle to recover someone the Vilebranch have taken.",
        sources = {"https://classicdb.ch/?quest=7845", "https://classicdb.ch/?quest=7850", "https://classicdb.ch/?quest=2993", "https://classicdb.ch/?quest=2994", "https://warcraft.wiki.gg/wiki/Jintha%27alor"},
        names = {"Jintha'alor"},
        related = {"faction:vilebranch", "faction:revantusk", "region:5468652048696e7465726c616e6473"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "place:shadraalor",
        title = "Shadra'Alor",
        kind = "Place",
        body = "Shadra'Alor is a Witherbark troll settlement in the southwestern Hinterlands. The trolls worship Shadra, a spider god, and venomous spiders are abundant around the settlement. Its altars make it a center of that worship as well as a home for the tribe.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #2934, #2936–2937", "https://warcraft.wiki.gg/wiki/Shadra%27Alor (original settlement and location)"},
        names = {},
        related = {"region:5468652048696e7465726c616e6473", "faction:witherbark"},
        setting = "Classic / Forever",
        autoLink = true},
    P("queldanil", "Quel'Danil Lodge", "#2995",
        "Quel'Danil Lodge served as a center of communication for the Hinterlands' high elves. Highvale ambassadors stored documents there about their contacts with other peoples and their knowledge of the Witherbark trolls."),
    P("skulk-rock", "Skulk Rock", "#77; #2877",
        "The Horde's abandoned positions near Skulk Rock became infested with slimes and oozes. The Wildhammers wanted the area cleared for their own expansion, while abandoned crates still attracted seekers of Hinterlands Honey Ripple."),
    P("eldarath", "Ruins of Eldarath", "#3449",
        "The ruins of Eldarath preserved runes and tablets left in public places by ancient elven mages. Researchers sought copies of these arcane teachings, though they were far from the only visitors interested in the ruins."),
    P("jaedenar", "Jaedenar", "#5155; #5157",
        "The Shadow Council occupied corrupted barrow dens at Jaedenar and plotted there with the Burning Legion. Deeper within lay Shadow Hold, where protective braziers screened the Council's chambers from magical observation."),
    P("shadow-hold", "Shadow Hold", "#5157",
        "Shadow Hold was the Shadow Council's inner stronghold beneath Jaedenar. Magical braziers protected it against scrying, prompting a plan to extinguish them with purified water from Jaedenar's corrupted moonwell."),
    P("shatter-scar", "Shatter Scar Vale", "#5156",
        "The craters of Shatter Scar Vale marked where infernals had fallen during the last great war. Infernals and entropic elementals remained there, while fetid water in the craters frustrated hopes of finding a clean source to help heal Felwood."),
    P("bloodvenom", "Bloodvenom Post", "#6605",
        "Bloodvenom Post stood in western Felwood. Winna Hazzard worked there, drawing the attention of travelers through her unusual and intensely focused research interests."),
    P("timbermaw-hold", "Timbermaw Hold", "#4521; #8460; #8461",
        "Timbermaw territory lay along the way from Felwood into Winterspring. Its furbolgs distrusted outsiders after repeated attacks on their people, but help against the corrupted Deadwood could gradually earn a welcome within the hold.", nil, {"faction:timbermaw"}),
    P("frostfire", "Frostfire Hot Springs", "#5082; #4842",
        "The waters of Frostfire Hot Springs had strange properties that drew both researchers and Winterfall furbolgs. The furbolgs guarded the larger pools, while investigators suspected a connection to the demons far south in Darkwhisper Gorge."),
    P("frostsaber-rock", "Frostsaber Rock", "#5056",
        "Great cats gathered around Frostsaber Rock in northern Winterspring. Their matriarch Shy-Rotam fiercely defended her kind, and hunters believed an offering at her stone would provoke her to appear."),
    P("starfall", "Starfall Village", "#5249",
        "Wynd Nightchaser spent much of his time at Starfall Village in Winterspring. Travelers seeking to explore the region's ancient elven ruins were directed to him for knowledge of the harsh surrounding country."),
    P("mazthoril", "Mazthoril", "#5160",
        "The icy caves of Mazthoril held cobalt runes linked to Haleh, the matron protectorate. A scale from one of her flight could activate those runes and carry its bearer to her, allowing her to examine what the dragon had witnessed."),
    {id = "place:darkwhisper",
        title = "Darkwhisper Gorge",
        kind = "Place",
        body = "Darkwhisper Gorge is a maze of ravines and tunnels in the far south of Winterspring, at the foothills of Mount Hyjal. Hederine demons occupy its depths. Thick, muggy air and a darkening sky distinguish the approach from the snowy country farther north, and the gorge is one of the region's most dangerous concentrations of demons.\n\nThe Hederine are also a source of unusual magic-resistant material. Daio the Decrepit explains that their fel poison hardens into crystals called Tears of the Hederine. He seeks them for a prison casing strong enough to contain a doomguard.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #4842 Strange Sources, L21265", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #7582 The Prison's Casing, L27174", "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge (original World of Warcraft geography only)", "https://classicdb.ch/?quest=7582"},
        names = {},
        related = {"region:57696e746572737072696e67"},
        setting = "Classic / Forever",
        autoLink = true},
    {id = "place:darrowshire",
        title = "Darrowshire",
        kind = "Place",
        body = "Darrowshire is a ruined human village in the southern Eastern Plaguelands, destroyed in the fighting against the Scourge. Its dead have not all found rest. Some of the people who defended it now wander the Plaguelands as ghouls and flayers, their spirits held within the creatures they have become.\n\nPamela Redpath's ghost waits in the house where her aunt hid her when her father went to fight. She still wants her lost doll and hopes that her family will return. Her uncle Carlin survives, but learning that Pamela remains a restless spirit deepens his grief. Relics from the battle offer a way to reach her father's spirit and free it. For the living who remember Darrowshire, the village's fall is still a family loss as well as a lost defense.",
        sources = {"https://warcraft.wiki.gg/wiki/Darrowshire (original ruined village identity and geography)", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5142 Little Pamela; #5149 Pamela's Doll; #5211 Defenders of Darrowshire; #5241 Uncle Carlin; #5721 The Battle of Darrowshire"},
        names = {},
        related = {"npc:pamela", "event:darrowshire", "npc:carlin"},
        setting = "Classic / Forever"},
    P("northdale", "Northdale", "#5845",
        "Taelan Fordring made his final stand for the Silver Hand at the war-torn hamlet of Northdale. Believing the order destroyed, he threw down its standard there, leaving a symbol that his father later sought for his redemption."),
    P("andorhal", "Andorhal", "#105",
        "Araj the Summoner ruled the ruins of Andorhal from the remains of its center. Numerous Scourge and a formidable personal guard protected the lich, making the ruined city a major obstacle to those trying to reclaim the Plaguelands.", {"Ruins of Andorhal"}),
    P("hearthglen", "Hearthglen", "#1052; #5862",
        "Hearthglen was one of the Scarlet Crusade's strongholds in Lordaeron. Its guarded community included Taelan Fordring, and reaching him with evidence about his father required an illusion that could pass as a Scarlet soldier."),
    P("caer-darrow", "Caer Darrow", "#838",
        "The island of Caer Darrow held Scholomance, a school serving as a Scourge stronghold. Its locked entrance protected research that strengthened the enemy, prompting efforts to obtain a key and breach the school."),
    P("felstone-field", "Felstone Field", "#5216; #5021",
        "Felstone Field lay northwest of Andorhal and held one of the Scourge's plague cauldrons. Amid the decaying farm buildings, Janice Felstone's ghost remained preoccupied with a package she had meant to send before disaster overtook her."),
    P("dalsons-tears", "Dalson's Tears", "#5219",
        "The fields of a former farmhouse north of Andorhal became known as Dalson's Tears. A guarded plague cauldron stood there, brewing its own mixture of toxins for investigators to sample in the search for a counteragent."),
    P("writhing-haunt", "The Writhing Haunt", "#5222",
        "The Writhing Haunt lay close to Andorhal's ruined eastern walls. Its plague cauldron was one of several the defenders needed to study so they could introduce a counteragent into the Scourge's poisons.", {"Writhing Haunt"}),
    P("gahrrons-withering", "Gahrron's Withering", "#5225",
        "Gahrron's Withering was a farm near the boundary of the Eastern Plaguelands. Wraiths, ghosts and Cauldron Lord Soulwrath guarded its plague cauldron, making it a particularly dangerous target for those seeking samples of the toxins within."),
    P("writhing-deep", "The Writhing Deep", "#4135",
        "The Writhing Deep lay south of Feralas's gnoll camps. Raschal of Feathermoon investigated its insect-like creatures as a possible threat to the region, leaving a note that helped searchers follow his trail.", {"Writhing Deep"}),
    {id = "place:fire-plume",
        title = "Fire Plume Ridge",
        kind = "Place",
        body = "Fire Plume Ridge is the volcano at the center of Un'Goro Crater. Lava runs down its slopes, fire elementals inhabit the mountain, and a lake of molten rock lies near the summit. Amid the crater's thick jungle, the ridge is a conspicuous concentration of heat and elemental danger.\n\nKrakle studies that heat because he suspects a connection with Un'Goro's nearby hot springs. He has built a thermometer to compare hot spots around the volcano, using a temperature scale he calls Kraklenheit. His investigation begins with a question about the springs, rather than an established explanation of their source.\n\nThe summit lava also has a practical use. Krinkle Goodsteel describes it as hot enough to fuse thorium and bone, making the ridge a forge for the unfinished stem of a skeleton key.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #974 Finding the Source, L8923", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #5802 Fire Plume Forged, L24059", "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge (first paragraph only)", "https://classicdb.ch/?quest=974", "https://classicdb.ch/?quest=5802"},
        names = {},
        related = {"region:556e27476f726f20437261746572"},
        setting = "Classic / Forever",
        autoLink = true},
    P("terror-run", "Terror Run", "#3882",
        "Marshal Expeditions planned to excavate ancient stegodon and diemetradon remains at Terror Run. Living beasts of the same kinds made the work dangerous enough that the expedition's chief digger sought less conventional ways to obtain the bones."),
    {id = "place:slithering-scar",
        title = "The Slithering Scar",
        kind = "Place",
        body = "The Slithering Scar is a silithid hive in southern Un'Goro Crater, occupied by the Gorishi. Its underground network contains larval hatcheries, with young insects hanging within the chambers. Giant wasps also live inside and around the hive, making the Scar a center of insect life distinct from the crater's surrounding wildlife.\n\nHol'anyee Marshal studies the Gorishi because she considers their presence foreign to Un'Goro's ecology. She seeks scrapings from a hatchery wall to investigate how the insects fit into the region. The hive's creatures also supply unusual materials: Torwa Pathfinder seeks Gorishi stings as one ingredient in a nonlethal toxin intended to pacify a large creature of the crater.",
        sources = {"StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #3883 Alien Ecology, L19180", "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt #9052 Bloodpetal Poison, L32943", "https://warcraft.wiki.gg/wiki/Slithering_Scar (hive identity only)", "https://classicdb.ch/?quest=3883"},
        names = {"Slithering Scar"},
        related = {"group:silithid", "region:556e27476f726f20437261746572"},
        setting = "Classic / Forever",
        autoLink = true},
    P("southwind", "Southwind Village", "#1125",
        "Southwind Village had once supported night elf operations in Silithus before the silithid overran it. The spirits of druids and sentinels still wandered its ruins, while the nearby hive threatened any attempt to work there again."),
    P("crystal-vale", "The Crystal Vale", "#6805",
        "Air and earth elementals guarded objects of power in Silithus's Crystal Vale. The Hydraxian Waterlords regarded them as enemies and sought to disrupt their work, though even the Waterlords' spokesman did not explain what the guarded objects were for.", {"Crystal Vale"}),
    P("gurubashi-arena", "Gurubashi Arena", "#7810",
        "A pirate ran the contests at Gurubashi's arena and challenged those seeking recognition as its master. Possessing a single arena trinket was only the beginning of proving oneself to him."),
    {id = "place:deeprun-tram", title = "Deeprun Tram", kind = "Place",
        body = "The Deeprun Tram connected Stormwind and Ironforge, with stations in the Dwarven District and Tinker Town. Monty supplied his brother Nipsy's rat-kabob business at the opposite end.",
        sources = {V .. " #6661; #6662", "https://worldofwarcraft.blizzard.com/en-us/news/23156366/wow-classic-getting-around-azeroth"}},
    {id = "place:mirage-raceway", title = "Mirage Raceway", kind = "Place",
        body = "Gnome and goblin teams raced rocket cars across the Shimmering Flats. Wrecked vehicles left parts scattered through the salt flats, and Kravel found a market for the salvage.",
        sources = {V .. " #1110", "https://classic-wow-archive.fandom.com/wiki/Shimmering_Flats"}},
    P("kargath", "Kargath", "#4133; #4769",
        "Kargath was an orcish outpost in the Badlands. Vivian Lagrave pursued reports of Dark Iron brews and ancient alchemical writings there, seeking help to retrieve the knowledge held within Blackrock Mountain."),
    P("stonard", "Stonard", "#1418; #1420; #568",
        "Stonard relied on couriers to maintain contact with the distant outpost of Kargath. Hostile country often interrupted that communication, while the defenders of Grom'gol worked to keep Stonard's supply route secure."),
    P("valormok", "Valormok", "#3504",
        "Valormok lay north of the Haldarr Encampment in Azshara. Ag'tor reported that the mage Rimtori had killed the warriors sent to protect her, leaving the camp badly weakened and its surviving agents seeking help."),
    P("pestles-apothecary", "Pestle's Apothecary", "#61; #60",
        "Morgan and William Pestle ran an apothecary in Stormwind's Trade District. William gathered candle wax in Elwynn and sent shipments to Morgan, whose shop sold potions and other useful wares."),
    P("valley-honor", "Valley of Honor", "#2976",
        "Belgrom Rockmaul received reports in Orgrimmar's Valley of Honor. News and trophies from Feralas reached him there, linking the city's officers to Horde operations across Kalimdor."),
    P("valley-strength", "Valley of Strength", "#6384",
        "Gryshka's inn stood in the Valley of Strength, near Orgrimmar's Skytower. Wind riders brought travelers and deliveries from the Barrens, including meat supplied for the inn by Zargh."),
    P("valley-spirits", "Valley of Spirits", "#5642",
        "The Valley of Spirits in Orgrimmar was a place of instruction for troll priests. Messengers called promising students back there when they were ready to learn another rite of their faith."),
    P("drag", "The Drag", "#32",
        "Zilzibin Drumlore lived on the second tier of the Drag in Orgrimmar. The scholar's knowledge of Azeroth's unusual life forms made his home a destination for reports on the silithid spreading through Tanaris.", {"Drag"}),
    P("trade-district", "Trade District", "#61",
        "Stormwind's Trade District included Pestle's Apothecary, where Morgan Pestle received supplies gathered by his brother in Elwynn. Local shops connected the capital's business to the work and materials of its surrounding countryside."),
    P("old-town", "Old Town", "#135",
        "Mathias Shaw, head of SI:7, could be found at the barracks in Stormwind's Old Town. Investigators seeking the truth behind the Defias Brotherhood were directed there for his knowledge of the city's secrets."),
    P("mage-quarter", "Mage Quarter", "#1075",
        "Collin Mauren worked in Stormwind's Mage Quarter. His magical expertise was sought for practical inventions as well as study, including a spell that would let an engineer detonate explosives from a distance."),
    P("cathedral-square", "Cathedral Square", "#373",
        "Stormwind's City Hall stood in Cathedral Square, where city architect Baros Alexston received correspondence. An unsent letter from Edwin VanCleef linked his office to the unresolved grievances behind the Defias Brotherhood."),
    P("dwarven-district", "Dwarven District", "#322",
        "Grimand Elmore practiced weaponsmithing in Stormwind's Dwarven District. His skill with Lightforge Iron made him a vital contact for those seeking a weapon against the necromancer Morbent Fel."),
    P("tinker-town", "Tinker Town", "#1072",
        "Lomac Gearstrip worked in Tinker Town, where engineers sought his expertise with powerful explosives. Gaxim Rustfizzle turned to him for the special mixture needed to make an advanced demolition device work."),
    P("mystic-ward", "Mystic Ward", "#1879",
        "The Hall of Mysteries lay within Ironforge's Mystic Ward. Bink instructed young mages there and sought capable students for work that required more than ordinary promise."),
    P("military-ward", "Military Ward", "#1679",
        "Ironforge's Military Ward housed the Hall of Arms. Muren Stormpike trained warriors there, receiving recruits from Dun Morogh who were ready to move beyond their first lessons."),
    P("forlorn-cavern", "The Forlorn Cavern", "#653",
        "Gerrig Bonegrip kept a shop in Ironforge's Forlorn Cavern. His knowledge of summoning connected the district to Myzrael, the imprisoned being whose promises drew others into her struggle against her guardians.", {"Forlorn Cavern"}),
    P("great-forge", "The Great Forge", "#1680",
        "Tormus Deepforge worked at Ironforge's Great Forge. Warriors sent by Muren Stormpike sought weapons from him, though his help could come with a dangerous task of its own.", {"Great Forge"}),
    P("hall-explorers", "Hall of Explorers", "#514",
        "The Hall of Explorers in Ironforge contained a library where Prospector Stormpike could be consulted. His skill at deciphering documents drew correspondence from scholars as far away as Southshore."),
    P("magic-quarter", "Magic Quarter", "#405",
        "Bethor Iceshard worked in the Undercity's Magic Quarter. Magistrate Sevren sent proven agents to him for a dangerous attempt to recruit a wayward lich, extending the Forsaken's struggle through arcane means."),
    P("war-quarter", "War Quarter", "#5644",
        "Aelthalyste awaited priest students in the Undercity's War Quarter. Teachers elsewhere sent promising pupils back to her when they were ready for lessons in the deeper powers of their faith."),
    P("apothecarium", "The Apothecarium", "#4642",
        "The Apothecarium supported experiments into strange creatures and their properties. Studies comparing oozes from corrupted Felwood with those of Un'Goro sought to understand how their environments altered them, research that interested Lady Sylvanas.", {"Apothecarium"}),
    P("trade-quarter", "Trade Quarter", "#441",
        "Raleigh lived in the Undercity's Trade Quarter. He recognized a ring brought from Brill as his wife Deliah's. He professed no grief for her death or the abduction of her body, but still desired revenge."),
    {id = "place:old-ironforge", title = "Old Ironforge", kind = "Place", setting = "Forever",
        body = "Caverns beneath Old Ironforge led into the Hall of Thanes and its lower vaults. A Dark Iron incursion there threatened the city from below, prompting a warning to King Magni and plans to seal the breaches.",
        sources = {V .. " #96393 Old Ironforge Incursion"}},
    {id = "place:lordamere-overlook", title = "Lordamere Overlook", kind = "Place", setting = "Forever",
        body = "Reports from Lordamere Overlook described an unholy fog filling the streets and graveyard within the Ruins of Lordaeron. Scouts attributed it to Rath'mael, whose magic gave the Scourge cover from the Forsaken.",
        sources = {V .. " #92422 The Wrath of Rath'mael"}},
})
